END_PAD = 2.60
def build():
    N = narr.build(); by = {s["id"]: s for s in N}
    def tref(r):
        if r[0] == "@": return float(r[1:]), None
        m = re.match(r"([sx]\d+)\.(\d+)([+-][\d.]+)?$", r); s = by[m.group(1)]; c = s["captions"][int(m.group(2))]
        off = float(m.group(3) or 0)
        return c["t0"] + off, (c["text"] if off == 0 else None)
    rows = []; scene = None
    for h in H:
        if isinstance(h, str): scene = h; continue
        t, word = tref(h[0]); rows.append([scene, t, word] + list(h[1:]))
    out = []
    end = rows[-1][1] + END_PAD
    for i, r in enumerate(rows):
        t0 = r[1]; t1 = rows[i + 1][1] if i + 1 < len(rows) else end
        f0 = int(round(t0 * FPS)); f1 = int(round(t1 * FPS))
        assert f1 - f0 >= 8, (i, r[0], t0, t1)
        cov = []
        for s in N:
            caps = [c["text"] for c in s["captions"] if c["t0"] < t1 - 0.02 and c["t1"] > t0 + 0.02 and (min(c["t1"], t1) - max(c["t0"], t0)) > 0.25 * (c["t1"] - c["t0"])]
            if caps: cov.append(dict(id=s["id"], captions=caps))
        out.append(dict(id="S%d" % (25 + i), scene=r[0], t0=round(t0, 3), t1=round(t1, 3), f0=f0, f1=f1, frames=f1 - f0, cls=r[3], set=r[4], size=r[5],
                        action=r[6], camera=r[7], lens=r[8], reads=r[9], sound=r[10], narration=cov, cut_on=r[2] or "(picture beat, no word)"))
    return N, out
if __name__ == "__main__":
    N, o = build()
    from collections import Counter
    c = Counter(); n = Counter()
    for s in o: c[s["cls"]] += s["frames"]; n[s["cls"]] += 1
    print(len(o), "shots", o[0]["f0"], o[-1]["f1"], o[-1]["t1"], dict(c), dict(n))
    tot = o[-1]["f1"] - o[0]["f0"]; print("avg", tot / 24 / len(o))
    for s in o:
        if s["frames"] > 84 or s["frames"] < 20: print(s["id"], s["cls"], s["frames"], s["cut_on"])
    for a, b in zip(o, o[1:]):
        if a["cls"] == b["cls"] and a["size"] == b["size"] and a["set"] == b["set"]: print("same size b2b", a["id"], b["id"], a["size"])
    sc = Counter(); 
    for s in o: sc[(s["scene"], s["set"])] += s["frames"]
    print(sorted(sc.items()))
